// What a tracker add-on reads from the page's request when connecting a
// board: its fields, the label that marks the factory's work, and the
// board's columns as the owner matched them to the factory's stages.
import { Refused } from "../refused.js";
import { stagesFrom } from "./stages.js";
// The stages as the owner matched them to the board's columns.
export function stagesOf(body, columns) {
    try {
        return stagesFrom(body?.stages, columns);
    }
    catch (error) {
        throw new Refused(error instanceof Error ? error.message : String(error));
    }
}
// The label that marks the factory's work: * (all of it) unless the owner
// chose another, or * for all of it.
export function labelOf(body) {
    const label = field(body, "label").trim() || "*";
    if (!/^(\*|[\w .:-]+)$/.test(label))
        throw new Refused(`“${label}” cannot be a label: use letters, digits, spaces, . : - or *.`);
    return label;
}
export function field(body, key) {
    const value = body?.[key];
    if (typeof value === "number")
        return String(value);
    return typeof value === "string" ? value : "";
}
